const chatId = $node["Путеводитель + StaticData"].json.chatId;

const sd = $getWorkflowStaticData('global');
sd.users = sd.users || {};
const key = `u_${chatId}`;
const user = sd.users[key] || {};

const raw =
  (typeof $json.output === 'string' && $json.output) ||
  (typeof $json.text === 'string' && $json.text) ||
  (typeof $json.response === 'string' && $json.response) ||
  '';

const trimmed = raw.trim();

let data;
try {
  data = JSON.parse(trimmed);
} catch (e) {
  const start = trimmed.indexOf('{');
  const end = trimmed.lastIndexOf('}');
  if (start === -1 || end === -1 || end <= start) {
    throw new Error('AI не вернул JSON. Начало ответа: ' + trimmed.slice(0, 200));
  }
  const jsonStr = trimmed.slice(start, end + 1);
  data = JSON.parse(jsonStr);
}

const topics = Array.isArray(data.topics) ? data.topics : [];

//очередь постов
const queueDraft = topics.map(t => ({
  topic: String(t.title || 'Тема').trim(),
  concepts: Array.isArray(t.concepts) ? t.concepts.map(x => String(x).trim()).filter(Boolean) : [],
}));

user.draft = { goal: data.goal || '', level: data.level || '', topics };
user.queueDraft = queueDraft;
user.cursor = 0;
user.state = 'WAIT_CONFIRM';

sd.users[key] = user;

const planText = topics
  .map((t, i) => {
    const title = (t.title || `Тема ${i + 1}`).trim();
    const concepts = Array.isArray(t.concepts) ? t.concepts : [];
    return `Тема ${i + 1}: ${title}\n[${concepts.join(', ')}]`;
  })
  .join('\n\n');

return [
  {
    json: {
      chatId,
      planText,
    },
  },
];

const chatId = $node["Путеводитель + StaticData"].json.chatId;
const userText = ($node["Путеводитель + StaticData"].json.text || '').trim();
const t = userText.toLowerCase();

const sd = $getWorkflowStaticData('global');
sd.users = sd.users || {};
const key = `u_${chatId}`;
const user = sd.users[key] || { state: 'WAIT_GOAL' };

const yes = ['да'];
const isYes = yes.includes(t);

let confirmed = false;
let messageForFalse = 'Хорошо! Тогда напиши новую тему и уровень (например: "SQL, начинающий").';

if (user.state === 'WAIT_CONFIRM') {
  if (isYes) {

    user.plan = user.draft;
    user.queue = user.queueDraft || [];
    user.cursor = 0;
    user.state = 'POSTING';
    delete user.draft;
    delete user.queueDraft;
    confirmed = true;
  } else {

    user.state = 'WAIT_GOAL';
    delete user.draft;
    delete user.queueDraft;
    delete user.plan;
    delete user.queue;
    user.cursor = 0;
    confirmed = false;
  }
} else if (user.state === 'POSTING') {
  const cursor = Number(user.cursor || 0);
  const queue = user.queue || [];
  if (cursor >= queue.length) {
    user.state = 'WAIT_GOAL';
    confirmed = false;
    messageForFalse = 'Мы прошли весь план \n\nЧто хочешь изучать дальше? Напиши тему и уровень.';
  } else {
    confirmed = true;
  }
} else {
  user.state = 'WAIT_GOAL';
  confirmed = false;
  messageForFalse = 'Давай начнём заново. Напиши тему и уровень.';
}

sd.users[key] = user;

const cursor = Number(user.cursor || 0);
const queue = user.queue || [];
const item = queue[cursor] || {};

return [{
  json: {
    chatId,
    confirmed,
    messageForFalse,
    topic: item.topic || '',
    concepts: item.concepts || '',
    cursor,
  }
}];

const base = $node["JS Post Prep"].json;

const raw =
  (typeof $json.output === 'string' && $json.output) ||
  (typeof $json.text === 'string' && $json.text) ||
  '';

const m = raw.match(/tavily\(\s*query\s*=\s*"([^"]+)"\s*\)/i);
const tavilyQuery = m ? m[1] : `${base.topic}`.trim();

return [{
  json: {
    chatId: base.chatId,
    topic: base.topic,
    concept: base.concept,
    cursor: base.cursor,
    tavilyQuery,
  }
}];

const ctx = $node["JS Parse Tavily"].json;

const chatId = ctx.chatId;
const topic = ctx.topic;
const concept = ctx.concept;
const cursor = Number(ctx.cursor || 0);

const answer = $json.answer || '';
const results = $json.results || [];

const sd = $getWorkflowStaticData('global');
sd.users = sd.users || {};
const key = `u_${chatId}`;
const user = sd.users[key] || {};
user.cursor = cursor + 1;
sd.users[key] = user;

const tavilyJson = JSON.stringify({ answer, results }, null, 2);

const postPrompt =
`Тема: "${topic}"
Понятие: "${concept}"

Ответ Tavily (JSON):
${tavilyJson}

Сформулируй лаконичный обучающий пост (800–1200 знаков):
- объясни тему простыми словами
- 1 определение
- 2 практических применения
- опирайся только на Tavily, не придумывай факты
- если уместно, добавь 1 ссылку из results`;

return [{
  json: {
    chatId,
    postPrompt
  }
}];

