const msg = $json.message;
if (!msg || !msg.chat || !msg.chat.id) {
  throw new Error('Не найден chat.id');
}

const chatId = msg.chat.id;
const text = (msg.text || '').trim();
const lower = text.toLowerCase();

const sd = $getWorkflowStaticData('global');
sd.users = sd.users || {};

const key = `u_${chatId}`;
const u = sd.users[key] || { state: 'ASK' };
const before = u.state;

if (lower === '/reset' || lower === 'reset') {
  u.state = 'WAIT_GOAL';
  delete u.goalText;
  delete u.plan;
  delete u.queue;
  u.cursor = 0;

  sd.users[key] = u;

  return [{
    json: {
      chatId,
      text,
      route: 'ASK',
      before,
      after: u.state
    }
  }];
}

let route = 'ASK';

if (u.state === 'ASK') {
  u.state = 'WAIT_GOAL';
  route = 'ASK';

} else if (u.state === 'WAIT_GOAL') {
  if (text) {
    u.goalText = text;
    route = 'PLAN';
  } else {
    route = 'ASK';
  }

} else {
  route = 'POST';
}

sd.users[key] = u;

return [{
  json: {
    chatId,
    text,
    route,
    before,
    after: u.state
  }
}];
